/*
 * One-use, RAM-only SMS capability broker, no I/O or modem commands.
 * DOES NOT authenticate the user; a privileged caller MUST supply a
 * trusted session binding and random nonce generated by the server.
 * No persistent tokens, OTP, SMS text or debug output.
 */
#include "veci-sms-read-capability.h"
#include <errno.h>
#include <stddef.h>
#include <stdint.h>

static void wipe(void *ptr, size_t count)
{
    volatile unsigned char *p = (volatile unsigned char *)ptr;
    while (count--) *p++ = 0;
}

static int nonzero(const unsigned char *p, size_t n)
{
    size_t i;
    unsigned int acc = 0;
    for (i = 0; i < n; ++i) acc |= p[i];
    return acc != 0;
}

static int constant_time_eq(const unsigned char *a,
                            const unsigned char *b, size_t n)
{
    size_t i;
    unsigned int diff = 0;
    for (i = 0; i < n; ++i) diff |= (unsigned int)(a[i] ^ b[i]);
    return diff == 0;
}

void veci_sms_cap_clear(struct veci_sms_read_capability *c)
{
    if (c) wipe(c, sizeof(*c));
}

int veci_sms_cap_arm(struct veci_sms_read_capability *c,
                     const unsigned char session[VECI_SMS_SESSION_BYTES],
                     const unsigned char token[VECI_SMS_CAP_BYTES],
                     unsigned int slot, uint64_t generation,
                     uint64_t now, unsigned int ttl,
                     int authorized, int csrf, int consent)
{
    unsigned int i;
    if (!c || !session || !token) return -EINVAL;
    if (c->state != VECI_SMS_CAP_EMPTY) return -EBUSY;
    if (slot > 65535u || !generation || !now ||
        !ttl || ttl > VECI_SMS_CAP_MAX_TTL_MS ||
        now > UINT64_MAX - ttl ||
        authorized != 1 || csrf != 1 || consent != 1 ||
        !nonzero(session, VECI_SMS_SESSION_BYTES) ||
        !nonzero(token, VECI_SMS_CAP_BYTES))
        return -EACCES;

    for (i = 0; i < VECI_SMS_SESSION_BYTES; ++i)
        c->trusted_session[i] = session[i];
    for (i = 0; i < VECI_SMS_CAP_BYTES; ++i)
        c->nonce[i] = token[i];
    c->generation = generation;
    c->slot = slot;
    c->armed_ms = now;
    c->expires_ms = now + ttl;
    c->state = VECI_SMS_CAP_READY;
    return 0;
}

int veci_sms_cap_consume(struct veci_sms_read_capability *c,
                         const unsigned char session[VECI_SMS_SESSION_BYTES],
                         const unsigned char nonce[VECI_SMS_CAP_BYTES],
                         unsigned int slot, uint64_t generation,
                         uint64_t now)
{
    int ok;
    if (!c || !session || !nonce) return -EINVAL;
    if (c->state != VECI_SMS_CAP_READY) return -EACCES;
    /* Consume BEFORE evaluating any checks: no failed attempt may later
     * succeed using the same token. Strict fail-closed single-use policy.
     */
    ok = constant_time_eq(c->trusted_session, session,
                          VECI_SMS_SESSION_BYTES) &
         constant_time_eq(c->nonce, nonce, VECI_SMS_CAP_BYTES) &
         (c->slot == slot) &
         (c->generation == generation) &
         (now >= c->armed_ms) &
         (now < c->expires_ms);
    wipe(c->trusted_session, sizeof(c->trusted_session));
    wipe(c->nonce, sizeof(c->nonce));
    c->slot = 0;
    c->generation = 0;
    c->armed_ms = 0;
    c->expires_ms = 0;
    c->state = VECI_SMS_CAP_USED;
    return ok ? 0 : -EACCES;
}
